//! Queries generated by FerrumData for table browsing, in each engine's query
//! language. Identifiers are always quoted with the engine's rules; no user
//! data is interpolated.

use ferrumdata_domain::{DatabaseEngine, TableInfo};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BrowseQuery {
    pub sql: String,
    /// False when the table has no primary key: row order may change between runs.
    pub deterministic: bool,
}

/// `SELECT * FROM "schema"."table" ORDER BY <pk> LIMIT max_rows + 1` for SQL
/// engines and SurrealDB; `db.getCollection("c").find({}).sort({"_id": 1}).limit(n)`
/// for MongoDB. The extra row lets the driver detect truncation at `max_rows`.
#[must_use]
pub fn browse_query(engine: DatabaseEngine, info: &TableInfo, max_rows: usize) -> BrowseQuery {
    let limit = max_rows.saturating_add(1);
    let deterministic = !info.primary_key.is_empty();
    if engine == DatabaseEngine::MongoDb {
        let collection = engine.quote_ident(&info.table.name);
        let sort: Vec<String> = info
            .primary_key
            .iter()
            .map(|c| format!("{}: 1", engine.quote_ident(c)))
            .collect();
        let sort = if deterministic {
            format!(".sort({{ {} }})", sort.join(", "))
        } else {
            String::new()
        };
        return BrowseQuery {
            sql: format!("db.getCollection({collection}).find({{}}){sort}.limit({limit})"),
            deterministic,
        };
    }
    let mut sql = format!("SELECT * FROM {}", info.table.qualified(engine));
    if deterministic {
        let cols: Vec<String> = info
            .primary_key
            .iter()
            .map(|c| engine.quote_ident(c))
            .collect();
        sql.push_str(&format!(" ORDER BY {}", cols.join(", ")));
    }
    sql.push_str(&format!(" LIMIT {limit}"));
    BrowseQuery { sql, deterministic }
}

#[cfg(test)]
mod tests {
    use super::*;
    use ferrumdata_domain::{TableKind, TableRef};

    fn info(pk: &[&str]) -> TableInfo {
        TableInfo {
            table: TableRef {
                schema: Some("public".into()),
                name: "User".into(),
            },
            kind: TableKind::Table,
            primary_key: pk.iter().map(|s| (*s).to_owned()).collect(),
            estimated_rows: None,
        }
    }

    #[test]
    fn orders_by_quoted_primary_key() {
        let q = browse_query(DatabaseEngine::Postgres, &info(&["orgId", "id"]), 100);
        assert_eq!(
            q.sql,
            r#"SELECT * FROM "public"."User" ORDER BY "orgId", "id" LIMIT 101"#
        );
        assert!(q.deterministic);
    }

    #[test]
    fn dialects_quote_their_own_way() {
        let mut t = info(&["id"]);
        t.table.schema = None;
        assert_eq!(
            browse_query(DatabaseEngine::MySql, &t, 9).sql,
            "SELECT * FROM `User` ORDER BY `id` LIMIT 10"
        );
        assert_eq!(
            browse_query(DatabaseEngine::Sqlite, &t, 9).sql,
            r#"SELECT * FROM "User" ORDER BY "id" LIMIT 10"#
        );
        assert_eq!(
            browse_query(DatabaseEngine::SurrealDb, &t, 9).sql,
            "SELECT * FROM `User` ORDER BY `id` LIMIT 10"
        );
    }

    #[test]
    fn mongo_browse_is_a_find_in_the_query_syntax() {
        let mut t = info(&["_id"]);
        t.table.schema = None;
        t.table.name = "we\"ird".into();
        let q = browse_query(DatabaseEngine::MongoDb, &t, 99);
        assert_eq!(
            q.sql,
            r#"db.getCollection("we\"ird").find({}).sort({ "_id": 1 }).limit(100)"#
        );
        assert!(q.deterministic);
        assert!(ferrumdata_db_mongodb::query::parse(&q.sql).is_ok());
    }

    #[test]
    fn no_primary_key_is_flagged_non_deterministic() {
        let q = browse_query(DatabaseEngine::Postgres, &info(&[]), 10);
        assert_eq!(q.sql, r#"SELECT * FROM "public"."User" LIMIT 11"#);
        assert!(!q.deterministic);
    }
}
